css:
/* Eclipse's look (taken from the site): dark warm background, raised dark cards
   with a thin border, amber accents and buttons, Lato text. Laid out for a
   1920x1080 TV seen from the sofa (everything about 1.5x the site's size). */
@font-face { font-family: "Lato"; font-weight: 400; src: url("fonts/lato-400.woff2") format("woff2"); }
@font-face { font-family: "Lato"; font-weight: 700; src: url("fonts/lato-700.woff2") format("woff2"); }
:root {
  --bg: #16110e;
  --bar: #231c17;
  --paper: #211a15;
  --primary: #e08a2e;
  --primary-light: #e6a157;
  --text: #f3e6d8;
  --text-2: #a8968a;
  --divider: rgba(255, 255, 255, 0.12);
}
* { box-sizing: border-box; }
html, body { margin: 0; width: 1920px; height: 1080px; overflow: hidden; background: var(--bg); color: var(--text); font-family: Lato, Arial, sans-serif; font-size: 26px; }
.hidden { display: none !important; }
.app { position: relative; width: 100%; height: 100%; }

/* ── Top bar ── */
.bar { position: absolute; left: 0; right: 0; top: 0; height: 104px; background: var(--bar); border-bottom: 1px solid var(--divider); display: flex; align-items: center; padding: 0 120px; z-index: 2; }
.brand { display: flex; align-items: center; width: 330px; font-weight: 700; font-size: 34px; }
.brand img { width: 58px; height: 58px; margin-right: 16px; }
.nav { flex: 1; display: flex; justify-content: center; }
.nav-item { background: none; border: 0; color: var(--text); font: 400 27px Lato, Arial, sans-serif; padding: 12px 22px; margin: 0 4px; border-radius: 10px; outline: none; }
.nav-item.current { color: var(--primary); }
.nav-item.focused { background: var(--primary); color: #1b120a; }
.bar-right { width: 330px; display: flex; flex-direction: column; align-items: flex-end; }
.who { display: flex; align-items: center; font-weight: 700; font-size: 24px; }
.who .avatar { width: 50px; height: 50px; border-radius: 50%; background: #9c6020; color: #f3e6d8; display: inline-flex; align-items: center; justify-content: center; font-size: 22px; margin-right: 14px; }
.ver { color: var(--text-2); font-size: 18px; }

/* ── Screens (the screen scrolls by moving its inner part) ── */
.screen { position: absolute; left: 0; right: 0; top: 105px; bottom: 0; overflow: hidden; }
.app.bare .bar { display: none; }
.app.bare .screen { top: 0; }
.screen-in { padding: 0 0 140px; transition: transform 180ms ease-out; }

.home-hero { height: 430px; display: flex; align-items: center; justify-content: center; }
.home-hero img { width: 320px; height: 320px; }
.heading { padding: 70px 120px 50px; border-bottom: 1px solid var(--divider); margin-bottom: 56px; }
.heading h1 { margin: 0; font-size: 60px; font-weight: 700; }
.heading p { margin: 14px 0 0; color: var(--text-2); font-size: 28px; max-width: 1300px; }

/* Cards, like the site's: a picture, a title, a description, an amber button. */
.cards { display: flex; flex-wrap: wrap; padding: 0 106px; }
.cards.center { justify-content: center; }
.card { width: 396px; margin: 0 14px 34px; background: var(--paper); border: 1px solid var(--divider); border-radius: 14px; padding: 18px; color: var(--text); text-align: left; font: inherit; outline: none; transition: transform 120ms, box-shadow 120ms; }
.card .pic { width: 100%; height: 210px; border-radius: 6px; background: #0e0b09 center / cover no-repeat; }
.card h3 { margin: 18px 0 8px; font-size: 30px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.card p { margin: 0; opacity: 0.85; font-size: 22px; line-height: 1.4; height: 92px; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; }
.card .btn { display: inline-block; margin-top: 14px; padding: 8px 10px; color: var(--primary); font-size: 22px; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; border-radius: 6px; }
.card.focused { transform: scale(1.06); box-shadow: 0 0 0 5px var(--primary), 0 20px 44px rgba(0, 0, 0, 0.6); }
.card.focused .btn { background: var(--primary); color: #1b120a; }

/* A show: its picture behind the title, seasons as tabs, episodes as cards. */
.show-hero { position: relative; height: 470px; background: #0b0a0c center / cover no-repeat; display: flex; align-items: flex-end; padding: 0 120px 46px; }
.show-hero .shade { position: absolute; left: 0; right: 0; top: 0; bottom: 0; background: linear-gradient(to bottom, rgba(22, 17, 14, 0.2), rgba(22, 17, 14, 0.75) 60%, #16110e); }
.show-hero .in { position: relative; max-width: 1400px; }
.show-hero h1 { margin: 0; font-size: 72px; font-weight: 700; text-shadow: 0 4px 24px rgba(0, 0, 0, 0.7); }
.show-hero p { margin: 16px 0 0; font-size: 26px; line-height: 1.45; text-shadow: 0 2px 10px rgba(0, 0, 0, 0.8); max-height: 114px; overflow: hidden; }
.tabs { display: flex; padding: 0 120px; border-bottom: 1px solid var(--divider); margin: 30px 0 36px; }
.tab { background: none; border: 0; border-bottom: 4px solid transparent; color: var(--text-2); font: 700 26px Lato, Arial, sans-serif; padding: 14px 26px; margin-right: 6px; outline: none; }
.tab.current { color: var(--primary); border-bottom-color: var(--primary); }
.tab.focused { background: var(--primary); color: #1b120a; border-radius: 10px 10px 0 0; }
.card.episode { width: 316px; }
.episode h3 { margin: 0 0 4px; font-size: 26px; }
.episode .sub { color: var(--text-2); font-size: 21px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.episode .btn { margin-top: 18px; }

.message { padding: 0 120px; color: var(--text-2); font-size: 30px; }

/* ── Sign in: the website's sign-in card, bigger ── */
.signin { height: 1080px; display: flex; align-items: center; justify-content: center; }
.signin-card { width: 640px; background: var(--paper); border: 1px solid var(--divider); border-radius: 12px; padding: 48px 56px; text-align: left; }
.signin-card.wide { width: 980px; text-align: center; }
.signin-logo { width: 110px; height: 110px; display: block; margin: 0 auto 18px; }
.signin-card h2 { margin: 0 0 22px; font-size: 40px; font-weight: 400; text-align: center; }
.signin-note { margin: 0 0 30px; color: var(--text-2); font-size: 24px; line-height: 1.5; }
.signin-new { margin: 30px 0 0; color: var(--text-2); font-size: 22px; line-height: 1.5; text-align: center; }
.google { width: 100%; display: flex; align-items: center; justify-content: center; background: transparent; color: var(--text); border: 1px solid var(--divider); border-radius: 8px; padding: 20px; font: 400 28px Lato, Arial, sans-serif; outline: none; }
.google .g { width: 30px; height: 30px; margin-right: 18px; }
.google.focused { border-color: var(--primary); box-shadow: 0 0 0 4px var(--primary); }
.signin-step { margin: 8px 0; color: var(--text-2); font-size: 28px; }
.signin-url { font-size: 54px; font-weight: 700; color: var(--primary); margin: 6px 0 22px; }
.signin-code { display: inline-block; font-size: 84px; font-weight: 700; letter-spacing: 0.12em; background: #120e0b; border: 1px solid var(--divider); border-radius: 14px; padding: 18px 42px; margin: 12px 0 30px; }
.signin-waiting { display: flex; align-items: center; justify-content: center; color: var(--text-2); font-size: 24px; margin-bottom: 26px; }
.signin-waiting .spinner { margin-right: 16px; }
.signin-wait { display: flex; justify-content: center; margin-bottom: 20px; }
.link { background: none; border: 0; color: var(--primary); font: 700 24px Lato, Arial, sans-serif; padding: 10px 18px; border-radius: 8px; outline: none; }
.link.focused { background: var(--primary); color: #1b120a; }

/* Waiting */
.loading { display: flex; justify-content: center; padding-top: 240px; }
.spinner { width: 72px; height: 72px; border-radius: 50%; border: 7px solid rgba(255, 255, 255, 0.15); border-top-color: var(--primary); animation: spin 0.9s linear infinite; }
.spinner.small { width: 34px; height: 34px; border-width: 4px; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ── Player ── */
.player { position: fixed; left: 0; top: 0; width: 1920px; height: 1080px; background: #000; z-index: 10; }
.player video { width: 100%; height: 100%; background: #000; }
#avplayer { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
/* Samsung's player draws the video behind the page: everything over it must be see-through. */
body.av-playing, body.av-playing .player { background: transparent; }
body.av-playing .app, body.av-playing video { visibility: hidden; }
.subs { position: absolute; left: 160px; right: 160px; bottom: 120px; text-align: center; font-size: 46px; line-height: 1.3; pointer-events: none; transition: bottom 200ms; }
.subs span { background: rgba(0, 0, 0, 0.72); padding: 4px 16px; border-radius: 6px; box-decoration-break: clone; -webkit-box-decoration-break: clone; text-shadow: 0 2px 4px #000; }
.player-ui { position: absolute; left: 0; right: 0; bottom: 0; padding: 120px 120px 44px; background: linear-gradient(to bottom, transparent, rgba(0, 0, 0, 0.85)); transition: opacity 300ms; }
.player-ui.faded { opacity: 0; }
.subs.up { bottom: 300px; }
.player-title { font-size: 40px; font-weight: 700; margin-bottom: 26px; }
.player-bar { height: 10px; background: rgba(255, 255, 255, 0.25); border-radius: 5px; overflow: hidden; }
.player-done { height: 100%; width: 0; background: var(--primary); }
.player-row { display: flex; align-items: center; margin-top: 22px; font-size: 26px; }
.player-icon { width: 44px; font-size: 30px; color: var(--primary); }
.player-buttons { margin-left: auto; display: flex; }
.pbtn { margin-left: 14px; padding: 10px 20px; border: 1px solid rgba(255, 255, 255, 0.3); border-radius: 8px; font-size: 24px; }
.player-buttons.quiet .pbtn { opacity: 0.7; }
.pbtn.focused { background: var(--primary); border-color: var(--primary); color: #1b120a; }
.player-hint { margin-top: 18px; color: var(--text-2); font-size: 21px; }
.player-menu { position: absolute; right: 120px; bottom: 210px; min-width: 460px; background: rgba(27, 21, 17, 0.97); border: 1px solid var(--divider); border-radius: 12px; padding: 18px 0; box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6); }
.player-menu h4 { margin: 0 28px 10px; font-size: 22px; color: var(--text-2); font-weight: 400; text-transform: uppercase; letter-spacing: 0.08em; }
.pitem { padding: 14px 28px 14px 64px; font-size: 28px; position: relative; }
.pitem.on::before { content: "\2713"; position: absolute; left: 26px; color: var(--primary); }
.pitem.focused { background: var(--primary); color: #1b120a; }
.pitem.focused.on::before { color: #1b120a; }
/* "Continue from 12:34?" */
.player-resume { position: absolute; left: 50%; top: 50%; width: 820px; margin: -170px 0 0 -410px; background: rgba(27, 21, 17, 0.97); border: 1px solid var(--divider); border-radius: 14px; padding: 40px 48px; text-align: center; box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6); }
.resume-title { color: var(--text-2); font-size: 24px; margin-bottom: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.resume-text { font-size: 40px; margin-bottom: 34px; }
.resume-text b { color: var(--primary); }
.resume-btns { display: flex; justify-content: center; }
.resume-btns .pbtn { font-size: 28px; padding: 14px 34px; margin: 0 12px; }
.player-wait { position: absolute; left: 0; right: 0; top: 0; bottom: 0; display: flex; align-items: center; justify-content: center; pointer-events: none; }

.toast { position: fixed; left: 50%; bottom: 80px; width: 1100px; margin-left: -550px; background: var(--paper); border: 1px solid var(--primary); border-radius: 12px; padding: 22px 30px; font-size: 26px; text-align: center; z-index: 20; box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6); }

scripts.code:
/* Settings for the app. (Plain ES5 everywhere: 2017-2018 TVs run an old browser.) */
var ECLIPSE = {
  /** The Eclipse server the app gets its shows, movies and videos from. */
  server: "https://eclipse.sanitylabs.io",
  /**
   * The same server's address on your home network (Gilgamesh). At home the
   * app uses it instead: it doesn't go out to the internet and back, so
   * videos come about 3x faster. Away from home (or if it doesn't answer)
   * the app uses the address above. If Gilgamesh's home address changes,
   * change it here (or give Gilgamesh a fixed address on the router).
   */
  homeServers: ["http://192.168.1.2:48951"],
  /**
   * The server's TV addresses (On Web Request flows), each answering JSON:
   *   categories  [{ _id, name, graphic, description, link }]
   *   shows       ?id=<category>  [{ _id, name, graphic, description }]
   *   show        ?id=<show>      { _id, name, graphic, description, seasons: [[{ _id, name, season, episode, media }]] }
   *   movies      [{ _id, name, graphic, description, media }]
   *   play        ?id=<the episode's / movie's media>  the Media record: { src: "/api/files/..." }
   */
  hooks: {
    categories: "/hooks/tv_categories",
    shows: "/hooks/tv_shows",
    show: "/hooks/tv_show",
    movies: "/hooks/tv_movies",
    play: "/hooks/tv_play"
  }
};

/*
 * The TV remote: arrows move the focus to the nearest focusable thing
 * ([data-focus]) in that direction, OK/Enter chooses it, Back goes back.
 * On a computer (developing in Chrome) the keyboard does the same:
 * arrows, Enter, and Backspace or Escape for Back.
 *
 * While a handler is set with Remote.take(fn), every key goes to it instead
 * (the video player uses this).
 */
var Remote = (function() {
  var KEY = {
    LEFT: 37, UP: 38, RIGHT: 39, DOWN: 40, ENTER: 13,
    BACK: 10009, ESCAPE: 27, BACKSPACE: 8,
    PLAY: 415, PAUSE: 19, PLAY_PAUSE: 10252, STOP: 413, REWIND: 412, FAST_FORWARD: 417
  };
  var onBack = null, current = null, taker = null, onFocus = null;

  // On the TV, keys other than arrows/OK/Back must be asked for first.
  function registerTvKeys() {
    try {
      if (window.tizen && tizen.tvinputdevice) {
        ["MediaPlay", "MediaPause", "MediaPlayPause", "MediaStop", "MediaRewind", "MediaFastForward"].forEach(function(k) {
          try { tizen.tvinputdevice.registerKey(k); } catch (e) { /* not on this model */ }
        });
      }
    } catch (e) { /* not on a TV */ }
  }

  function focusables() {
    return Array.prototype.slice.call(document.querySelectorAll("[data-focus]")).filter(function(el) {
      return el.offsetParent !== null && !el.disabled;
    });
  }
  function focus(el) {
    if (!el) return;
    if (current && current !== el) current.classList.remove("focused");
    current = el;
    el.classList.add("focused");
    if (onFocus) onFocus(el);
  }
  // The nearest one in that direction (by the centres of the boxes; things in
  // line with the current one win over things off to the side).
  function move(dx, dy) {
    var all = focusables();
    if (!current || all.indexOf(current) < 0) { focus(all[0]); return; }
    var a = current.getBoundingClientRect(), ax = a.left + a.width / 2, ay = a.top + a.height / 2;
    var best = null, bestScore = Infinity;
    all.forEach(function(el) {
      if (el === current) return;
      var b = el.getBoundingClientRect(), bx = b.left + b.width / 2, by = b.top + b.height / 2;
      var along = dx ? (bx - ax) * dx : (by - ay) * dy;
      if (along <= 1) return;
      var across = dx ? Math.abs(by - ay) : Math.abs(bx - ax);
      // Moving sideways stays in the same row.
      if (dx && across > Math.max(a.height, b.height) / 2) return;
      var score = along + across * 3;
      if (score < bestScore) { bestScore = score; best = el; }
    });
    // Moving up or down into another row of tabs (the top bar, the seasons)
    // lands on its selected one, not just the nearest.
    if (best && dy && best.parentNode !== current.parentNode) {
      var chosen = best.parentNode.querySelector(".current[data-focus]");
      if (chosen && chosen.offsetParent !== null) best = chosen;
    }
    if (best) focus(best);
  }

  function exitApp() {
    try { tizen.application.getCurrentApplication().exit(); } catch (e) { /* in a browser: nothing to leave */ }
  }

  document.addEventListener("keydown", function(e) {
    var k = e.keyCode;
    var isBack = k === KEY.BACK || k === KEY.ESCAPE || (k === KEY.BACKSPACE && !/INPUT|TEXTAREA/.test((e.target || {}).tagName || ""));
    if (taker) {
      taker(isBack ? KEY.BACK : k);
      e.preventDefault();
      return;
    }
    if (k === KEY.LEFT) move(-1, 0);
    else if (k === KEY.RIGHT) move(1, 0);
    else if (k === KEY.UP) move(0, -1);
    else if (k === KEY.DOWN) move(0, 1);
    else if (k === KEY.ENTER) { if (current) current.click(); }
    else if (isBack) { if (!onBack || onBack() !== true) exitApp(); }
    else return;
    e.preventDefault();
  });

  // Letting go of a key: only a screen that takes every key (the player) is told.
  document.addEventListener("keyup", function(e) {
    if (taker) { taker(e.keyCode, true); e.preventDefault(); }
  });

  registerTvKeys();
  return {
    KEY: KEY,
    focus: focus,
    current: function() { return current; },
    focusFirst: function(within) {
      var all = focusables().filter(function(el) { return !within || within.contains(el); });
      focus(all[0]);
    },
    /** What Back does on this screen: return true when handled, else the app closes. */
    onBack: function(fn) { onBack = fn; },
    /** Called whenever the focus moves (the app scrolls it into view). */
    onFocus: function(fn) { onFocus = fn; },
    /** Send every key to fn(key) (or stop, with null); fn(key, true) when a key is let go. */
    take: function(fn) { taker = fn; },
    exitApp: exitApp
  };
})();

/*
 * Talking to the Eclipse server.
 *
 * Signing in: the TV keeps its sign-in token (from Google's TV sign-in,
 * signin.js) and sends it with every request in the X-Alc-Session header,
 * like a browser sends its sign-in cookie. Videos, pictures and subtitles
 * can't carry headers, so their addresses get ?alc_session=<token> (Api.media).
 * When the server says the sign-in has ended (401), the app goes back to the
 * sign-in screen.
 */
var Api = (function() {
  var KEY = "eclipse_session";
  var token = "";
  try { token = localStorage.getItem(KEY) || ""; } catch (e) { /* no storage */ }
  var onSignedOut = null;
  // The address used now: the home one when it answers, else the internet one.
  var base = ECLIPSE.server;

  function url(path) {
    if (!path) return "";
    return /^https?:/i.test(path) ? path : base + path;
  }
  function ours(u) { return u.indexOf(base + "/") === 0 || u.indexOf(ECLIPSE.server + "/") === 0; }

  /** Does this address answer like an Alchemist server, quickly? */
  function answers(address, ms) {
    return new Promise(function(resolve) {
      var x = new XMLHttpRequest();
      try { x.open("GET", address + "/api/health", true); } catch (e) { return resolve(false); }
      x.timeout = ms;
      x.onload = function() {
        var ok = false;
        try { ok = x.status === 200 && JSON.parse(x.responseText).status === "ok"; } catch (e) { /* not ours */ }
        resolve(ok);
      };
      x.onerror = x.ontimeout = function() { resolve(false); };
      x.send();
    });
  }
  /**
   * Picks the address: the first home address that answers within 1.5
   * seconds, else the internet one. Resolves to "home" or "internet".
   */
  function pickServer() {
    var list = (ECLIPSE.homeServers || []).slice();
    function next() {
      if (!list.length) { base = ECLIPSE.server; return Promise.resolve("internet"); }
      var a = String(list.shift()).replace(/\/+$/, "");
      return answers(a, 1500).then(function(ok) {
        if (ok) { base = a; return "home"; }
        return next();
      });
    }
    return next();
  }
  /** The home address stopped answering: use the internet one from now on. */
  function leaveHome() {
    if (base === ECLIPSE.server) return false;
    base = ECLIPSE.server;
    return true;
  }
  /** A video's, picture's or subtitle file's address, with the sign-in when needed. */
  function media(path) {
    if (!path) return "";
    var u = url(path);
    var rest = u.indexOf(base + "/") === 0 ? u.slice(base.length) : u.indexOf(ECLIPSE.server + "/") === 0 ? u.slice(ECLIPSE.server.length) : null;
    if (token && rest !== null && /^\/(api\/files\/|api\/subtitles|api\/audio-tracks|img\/)/.test(rest)) {
      u += (u.indexOf("?") < 0 ? "?" : "&") + "alc_session=" + encodeURIComponent(token);
    }
    return u;
  }

  /** A JSON request; fails with a plain-language reason (err.status = the HTTP status). */
  function request(method, address, body, ms, retried) {
    var p = new Promise(function(resolve, reject) {
      var x = new XMLHttpRequest();
      var full = url(address);
      x.open(method, full, true);
      x.timeout = ms || 20000;
      if (token && ours(full)) x.setRequestHeader("X-Alc-Session", token);
      if (body !== undefined) x.setRequestHeader("Content-Type", "application/json");
      x.onload = function() {
        var data = null;
        try { data = JSON.parse(x.responseText); } catch (e) { /* not JSON */ }
        if (x.status >= 200 && x.status < 300 && data !== null) return resolve(data);
        if (x.status === 204) return resolve(null);   // nothing found
        var err = new Error(data && data.error ? data.error : "the server answered " + x.status);
        err.status = x.status;
        err.data = data;
        // Signed in, but the server says not (signed out elsewhere, or 30 days passed).
        if (x.status === 401 && token && onSignedOut) onSignedOut();
        reject(err);
      };
      x.onerror = function() { var e = new Error("the Eclipse server can't be reached (is the TV online?)"); e.network = true; reject(e); };
      x.ontimeout = function() { var e = new Error("the Eclipse server didn't answer in time"); e.network = true; reject(e); };
      x.send(body !== undefined ? JSON.stringify(body) : null);
    });
    // The home address stopped answering (e.g. Gilgamesh got a new one): ask over the internet instead.
    if (retried || /^https?:/i.test(address)) return p;
    return p.then(null, function(err) {
      if (err.network && leaveHome()) return request(method, address, body, ms, true);
      throw err;
    });
  }
  function getJson(address, ms) { return request("GET", address, undefined, ms); }

  function q(address, id) { return address + "?id=" + encodeURIComponent(id); }
  function num(v) { var n = parseInt(v, 10); return isNaN(n) ? 0 : n; }

  /**
   * A show's episodes as seasons, each sorted by episode number (the server's
   * lists can come in text order: 1, 10, 11, 2...).
   */
  function seasonsOf(show) {
    var all = [];
    (show.seasons || []).forEach(function(s) { (Array.isArray(s) ? s : [s]).forEach(function(e) { if (e) all.push(e); }); });
    var by = {};
    all.forEach(function(e) { var n = num(e.season) || 1; (by[n] = by[n] || []).push(e); });
    return Object.keys(by).map(Number).sort(function(a, b) { return a - b; }).map(function(n) {
      return { season: n, episodes: by[n].sort(function(a, b) { return num(a.episode) - num(b.episode); }) };
    });
  }

  return {
    url: url,
    media: media,
