  }
  function logout() {
    Api.logout().then(null, function() { /* signed out here either way */ });
    Api.setToken("");
    signIn();
  }
  // The server ended the sign-in (signed out elsewhere, or it ran out): sign in again.
  Api.onSignedOut(function() {
    if (signingIn) return;
    Api.setToken("");
    if (Player.isOpen()) Remote.take(null);
    signIn("ended");
  });

  // ── Version and updates ──
  function appVersion() {
    // Installed: the launcher says which version of the app it's running
    // (updates replace the app without reinstalling it).
    if (window.EclipseBoot) return EclipseBoot.version;
    try { return tizen.application.getCurrentApplication().appInfo.version; } catch (e) { /* in a browser */ }
    var m = document.querySelector('meta[name="app-version"]');
    return m ? m.getAttribute("content") : "0.0.0";
  }
  var version = appVersion();
  $("version").textContent = "Version " + version;

  // ── Which way the app reaches Eclipse: shown next to the version ──
  function showRoute() {
    $("version").textContent = "Version " + version + (Api.route() === "home" ? " \u00b7 home network" : " \u00b7 internet");
  }
  // Coming back to the app (e.g. after the TV was off): check again which way works.
  document.addEventListener("visibilitychange", function() {
    if (!document.hidden && !Player.isOpen()) Api.pickServer().then(showRoute);
  });

  // ── Start: signed in already? Otherwise the sign-in screen, like the site. ──
  function start() {
    loading();
    Api.pickServer().then(function() { showRoute(); begin(); });
  }
  function begin() {
    if (!Api.signedIn()) return signIn();
    Api.me().then(function(me) {
      if (me && me.signedIn) enter(me.user);
      else { Api.setToken(""); signIn("ended"); }
    }, function(err) {
      problem("Couldn't reach Eclipse: " + err.message, start);
    });
  }
  start();
  // Tell the launcher this version started fine (it then keeps it).
  if (window.EclipseBoot) EclipseBoot.ready();

  return { toast: toast };
})();
